void parseToFloatArray(const std::string& input, float* out_array) {
    std::istringstream stream(input);
    float value;
    int index = 0;
    
    // Extract floats, skipping spaces and newlines automatically
    while (stream >> value) {
        out_array[index++] = value;
    }
}

